export function __readergoStart(host) {
  const __readergoModule = (id) => {
    if (!host || typeof host.module !== "function") {
      throw new Error("ReaderGo plugin host is not installed");
    }
    return host.module(id);
  };
  const require = (id) => __readergoModule(id);
// plugins/sync-style/src/index.ts
var manifest = {
  id: "readergo.examples.sync-style",
  name: "Sync Style Example",
  version: "1.0.0",
  description: "Demonstrates obtaining generic capabilities from the host platform.",
  category: "feature",
  provides: [],
  requires: ["document-storage"],
  // Declares we need the document-storage capability to function
  permissions: ["note:read"]
};
var SyncStylePlugin = {
  manifest,
  async activate(context) {
    context.log.info("\u{1F504} Sync Style plugin activating...");
    const storageManager = await context.getCapability("document-storage");
    if (storageManager) {
      context.log.info("Successfully connected to document-storage capability!");
    } else {
      context.log.warn("Could not find document-storage capability. Is it loaded?");
    }
  },
  deactivate(context) {
    context.log.info("\u{1F504} Sync Style plugin deactivated.");
  }
};


  return { SyncStylePlugin: SyncStylePlugin };
}
